insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-14','en-b2-14',null,4,14,'published',1,'{"id":"en-b2-14","baseId":"en-b2-14","revision":1,"level":"B2","levelIndex":4,"order":14,"title":"Gerund va infinitive: ma’no o‘zgarishi","objective":"Remember, stop va try bilan shaklning ma’noga ta’sirini tushuntirasiz.","context":"Gerund va infinitive: ma’no o‘zgarishi","prerequisites":["en-b2-13"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik.","Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash.","Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish."],"pattern":"remember locking / remember to lock / stop to talk","examples":["I remember locking the door.","Please remember to lock the door.","We stopped talking.","We stopped to talk to the guide.","Try restarting the app.","I tried to open the heavy door."],"vocabulary":[{"id":"en-b2-14-v0","term":"attempt","meaning":"urinish","ipa":"/əˈtempt/","collocation":"make an attempt","example":"When the group edits practical messages, it asks whether the sentence describes memory, intention, a method, or an attempt."},{"id":"en-b2-14-v1","term":"method","meaning":"usul","ipa":"/ˈmeθəd/","collocation":"try a method","example":"When the group edits practical messages, it asks whether the sentence describes memory, intention, a method, or an attempt."},{"id":"en-b2-14-v2","term":"recall","meaning":"eslamoq","ipa":"/rɪˈkɔːl/","collocation":"recall an action","example":"A later note says, “Remember locking the equipment room.” This sounds like recalling an action, not asking someone to do it."},{"id":"en-b2-14-v3","term":"interrupt","meaning":"to‘xtatmoq","ipa":"/ˌɪntəˈrʌpt/","collocation":"interrupt an activity","example":"interrupt an activity"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["remember locking / remember to lock / stop to talk","I remember locking the door.","Please remember to lock the door."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Verb patterns encode different intentions.","Remembering an action differs from remembering to act.","Check the meaning, not just the ending."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We stopped to talk to the guide.","audio":"/english-course/v7.23/en-b2-14-dictation.mp3"},"exercises":[{"id":"en-b2-14-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Remember ___ lock the door.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","options":["to","for","that"]},{"id":"en-b2-14-gap","type":"grammarFill","skill":"grammar","prompt":"Remember ___ lock the door.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk"},{"id":"en-b2-14-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I remember locking the door."],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","tokens":["I","remember","locking","the","door."]},{"id":"en-b2-14-fix","type":"correction","skill":"grammar","prompt":"Please remember locking the room before you leave.","answers":["Please remember to lock the room before you leave."],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk"},{"id":"en-b2-14-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["urinish","usul","eslamoq","to‘xtatmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"remember locking / remember to lock / stop to talk","left":["attempt","method","recall","interrupt"],"options":["urinish","usul","eslamoq","to‘xtatmoq"]},{"id":"en-b2-14-transform","type":"transformation","skill":"grammar","prompt":"Xotira: I can recall that I locked the door.","answers":["I remember locking the door."],"hint":"remember locking / remember to lock / stop to talk","explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik."},{"id":"en-b2-14-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Verb patterns encode different intentions.","Remembering an action differs from remembering to act.","Check the meaning, not just the ending."],"answers":["Verb patterns encode different intentions.\nRemembering an action differs from remembering to act.\nCheck the meaning, not just the ending."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The club asks why a recorded interview contains a long pause. One student says they stopped talking; another says they stopped to talk to a guide outside. The first describes ending an activity, while the second gives the purpose of a pause in another activity. The organiser checks the timeline and finds that both happened at different points. A later note says, “Remember locking the equipment room.” This sounds like recalling an action, not asking someone to do it. The writer changes it to “Remember to lock the equipment room.” Small changes in verb patterns can affect instructions, not merely grammatical accuracy. When the group edits practical messages, it asks whether the sentence describes memory, intention, a method, or an attempt.","sentences":["The club asks why a recorded interview contains a long pause.","One student says they stopped talking; another says they stopped to talk to a guide outside.","The first describes ending an activity, while the second gives the purpose of a pause in another activity.","The organiser checks the timeline and finds that both happened at different points.","A later note says, “Remember locking the equipment room.","” This sounds like recalling an action, not asking someone to do it.","The writer changes it to “Remember to lock the equipment room.","” Small changes in verb patterns can affect instructions, not merely grammatical accuracy.","When the group edits practical messages, it asks whether the sentence describes memory, intention, a method, or an attempt."],"questions":[{"id":"en-b2-14-reading0","type":"choice","skill":"reading","prompt":"Remember to lock nimani bildiradi?","answers":["a required future action"],"explanation":"To lock vazifani eslatadi.","hint":"remember locking / remember to lock / stop to talk","options":["a required future action","a memory of locking","proof of a locked door"]},{"id":"en-b2-14-reading1","type":"choice","skill":"reading","prompt":"Ikki stop bayoni bir-biriga zidmi?","answers":["not necessarily, they refer to different points"],"explanation":"Timeline turli nuqtalar.","hint":"remember locking / remember to lock / stop to talk","options":["not necessarily, they refer to different points","always","both mean the same thing"]},{"id":"en-b2-14-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"remember locking / remember to lock / stop to talk","options":["The club asks why a recorded interview contains a long pause.","One student says they stopped talking; another says they stopped to talk to a guide outside.","The first describes ending an activity, while the second gives the purpose of a pause in another activity.","The organiser checks the timeline and finds that both happened at different points.","A later note says, “Remember locking the equipment room.","” This sounds like recalling an action, not asking someone to do it.","The writer changes it to “Remember to lock the equipment room.","” Small changes in verb patterns can affect instructions, not merely grammatical accuracy.","When the group edits practical messages, it asks whether the sentence describes memory, intention, a method, or an attempt."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is method. The club asks why a recorded interview contains a long pause. One student says they stopped talking; another says they stopped to talk to a guide outside. Speaker two: My main point is meaning. Verb patterns change what the instruction asks someone to do. The club asks why a recorded interview contains a long pause. One student says they stopped talking; another says they stopped to talk to a guide outside. The first describes ending an activity, while the second gives the purpose of a pause in another activity. The organiser checks the timeline and finds that both happened at different points. A later note says, “Remember locking the equipment room.” This sounds like recalling an action, not asking someone to do it. The writer changes it to “Remember to lock the equipment room.” Small changes in verb patterns can affect instructions, not merely grammatical accuracy. When the group edits practical messages, it asks whether the sentence describes memory, intention, a method, or an attempt.","audio":"/english-course/v7.23/en-b2-14.mp3","synthetic":true,"questions":[{"id":"en-b2-14-listening0","type":"choice","skill":"listening","prompt":"Remember to lock nimani bildiradi?","answers":["a required future action"],"explanation":"To lock vazifani eslatadi.","hint":"remember locking / remember to lock / stop to talk","options":["a required future action","a memory of locking","proof of a locked door"]},{"id":"en-b2-14-listening1","type":"choice","skill":"listening","prompt":"Ikki stop bayoni bir-biriga zidmi?","answers":["not necessarily, they refer to different points"],"explanation":"Timeline turli nuqtalar.","hint":"remember locking / remember to lock / stop to talk","options":["not necessarily, they refer to different points","always","both mean the same thing"]},{"id":"en-b2-14-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["method","meaning"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"remember locking / remember to lock / stop to talk","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-14-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We stopped to talk to the guide."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"remember locking / remember to lock / stop to talk","audio":"/english-course/v7.23/en-b2-14-dictation.mp3","transcript":"We stopped to talk to the guide."}]},"writing":{"task":"Amaliy yo‘riqnoma yozing, remember/stop/try juftliklarini ma’noda ajrating.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Before leaving, please remember to lock the equipment room. If the recording app freezes, try restarting it before changing any settings. During an interview, stop talking when the speaker needs time to think. If you need to ask the guide a question, stop the recording to talk rather than recording an unrelated conversation. I remember checking the battery last time, but that memory does not guarantee it is charged today. These instructions distinguish future actions, possible methods, and memories of completed work.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["I remember locking the door.","Please remember to lock the door.","We stopped talking."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Amaliy yo‘riqnoma yozing, remember/stop/try juftliklarini ma’noda ajrating. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Amaliy yo‘riqnoma yozing, remember/stop/try juftliklarini ma’noda ajrating.","exit":[[{"id":"en-b2-14-exit0","type":"grammarFill","skill":"grammar","prompt":"Remember ___ lock the door.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk"},{"id":"en-b2-14-exit1","type":"grammarFill","skill":"grammar","prompt":"I remember ___ the door. (lock)","answers":["locking"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk"},{"id":"en-b2-14-exit2","type":"grammarFill","skill":"grammar","prompt":"We stopped ___ talk to the guide.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk"},{"id":"en-b2-14-exit3","type":"choice","skill":"grammar","prompt":"Remember to lock nimani bildiradi?","answers":["a required future action"],"explanation":"To lock vazifani eslatadi.","hint":"remember locking / remember to lock / stop to talk","options":["a required future action","a memory of locking","proof of a locked door"]},{"id":"en-b2-14-exit4","type":"choice","skill":"grammar","prompt":"Ikki stop bayoni bir-biriga zidmi?","answers":["not necessarily, they refer to different points"],"explanation":"Timeline turli nuqtalar.","hint":"remember locking / remember to lock / stop to talk","options":["not necessarily, they refer to different points","always","both mean the same thing"]}],[{"id":"en-b2-14-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Please remember to lock the door."],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","tokens":["Please","remember","to","lock","the","door."]},{"id":"en-b2-14-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I remember ___ the door. (lock)","answers":["locking"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk"},{"id":"en-b2-14-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We stopped to talk to the guide."],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","tokens":["We","stopped","to","talk","to","the","guide."]},{"id":"en-b2-14-exit-b3","type":"choice","skill":"grammar","prompt":"Remember to lock nimani bildiradi?","answers":["a required future action"],"explanation":"To lock vazifani eslatadi.","hint":"remember locking / remember to lock / stop to talk","options":["a required future action","a memory of locking","proof of a locked door"]},{"id":"en-b2-14-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I tried to open the heavy door."],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","tokens":["I","tried","to","open","the","heavy","door."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-15','en-b2-15',null,4,15,'published',1,'{"id":"en-b2-15","baseId":"en-b2-15","revision":1,"level":"B2","levelIndex":4,"order":15,"title":"Articles va determiners: umumiydan aniqga","objective":"Umumiy guruh va ma’lum obyektni matn bo‘ylab izchil belgilaysiz.","context":"Articles va determiners: umumiydan aniqga","prerequisites":["en-b2-14"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt.","Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information.","Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university."],"pattern":"a proposal → the proposal / information / each student","examples":["We received a proposal.","The proposal needs more evidence.","Libraries provide information.","Each student has a role.","Both plans have advantages.","It takes an hour to reach a university."],"vocabulary":[{"id":"en-b2-15-v0","term":"reference","meaning":"ishora","ipa":"/ˈrefərəns/","collocation":"clear reference","example":"clear reference"},{"id":"en-b2-15-v1","term":"general","meaning":"umumiy","ipa":"/ˈdʒenərəl/","collocation":"a general claim","example":"She then writes that the libraries help children, although she means libraries in general rather than a known set."},{"id":"en-b2-15-v2","term":"specific","meaning":"aniq","ipa":"/spəˈsɪfɪk/","collocation":"a specific object","example":"She asks what the reader can already identify and whether the intended claim applies generally or specifically."},{"id":"en-b2-15-v3","term":"determiner","meaning":"aniqlovchi","ipa":"/dɪˈtɜːmɪnə/","collocation":"choose a determiner","example":"Her teacher also checks determiners: each student has a role, but both teams share one display."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["a proposal → the proposal / information / each student","We received a proposal.","The proposal needs more evidence."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Introduce one proposal.","Refer back to the same proposal.","Distinguish specific objects from general categories."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Each student has a role.","audio":"/english-course/v7.23/en-b2-15-dictation.mp3"},"exercises":[{"id":"en-b2-15-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: We received ___ proposal.","answers":["a"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","options":["a","an","no article"]},{"id":"en-b2-15-gap","type":"grammarFill","skill":"grammar","prompt":"We received ___ proposal.","answers":["a"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student"},{"id":"en-b2-15-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We received a proposal."],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","tokens":["We","received","a","proposal."]},{"id":"en-b2-15-fix","type":"correction","skill":"grammar","prompt":"Each student have a role.","answers":["Each student has a role."],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student"},{"id":"en-b2-15-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ishora","umumiy","aniq","aniqlovchi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"a proposal → the proposal / information / each student","left":["reference","general","specific","determiner"],"options":["ishora","umumiy","aniq","aniqlovchi"]},{"id":"en-b2-15-transform","type":"transformation","skill":"grammar","prompt":"Aniq oldingi obyekt: We received a proposal. This proposal needs evidence.","answers":["We received a proposal. The proposal needs evidence."],"hint":"a proposal → the proposal / information / each student","explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt."},{"id":"en-b2-15-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Introduce one proposal.","Refer back to the same proposal.","Distinguish specific objects from general categories."],"answers":["Introduce one proposal.\nRefer back to the same proposal.\nDistinguish specific objects from general categories."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-15-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["reference","general","specific","determiner"],"options":["clear reference","a general claim","a specific object","choose a determiner"],"answers":["clear reference","a general claim","a specific object","choose a determiner"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A student opens her report with a proposal for a reading corner. In the next sentence, the proposal refers to the same idea, so the definite article helps the reader follow it. She then writes that the libraries help children, although she means libraries in general rather than a known set. Removing the article makes the scope clearer. Her teacher also checks determiners: each student has a role, but both teams share one display. These choices are small, yet they tell readers whether the report describes one object, a known group, or a general category. The editor does not replace every article mechanically. She asks what the reader can already identify and whether the intended claim applies generally or specifically.","sentences":["A student opens her report with a proposal for a reading corner.","In the next sentence, the proposal refers to the same idea, so the definite article helps the reader follow it.","She then writes that the libraries help children, although she means libraries in general rather than a known set.","Removing the article makes the scope clearer.","Her teacher also checks determiners: each student has a role, but both teams share one display.","These choices are small, yet they tell readers whether the report describes one object, a known group, or a general category.","The editor does not replace every article mechanically.","She asks what the reader can already identify and whether the intended claim applies generally or specifically."],"questions":[{"id":"en-b2-15-reading0","type":"choice","skill":"reading","prompt":"Ikkinchi proposal nega the?","answers":["the reader can identify the earlier idea"],"explanation":"Avvalgi a proposalga qaytadi.","hint":"a proposal → the proposal / information / each student","options":["the reader can identify the earlier idea","every noun needs the","it begins with a consonant"]},{"id":"en-b2-15-reading1","type":"choice","skill":"reading","prompt":"Umumiy libraries oldida nima?","answers":["no article"],"explanation":"Umumiy ko‘plik zero article.","hint":"a proposal → the proposal / information / each student","options":["no article","always the","always an"]},{"id":"en-b2-15-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"a proposal → the proposal / information / each student","options":["A student opens her report with a proposal for a reading corner.","In the next sentence, the proposal refers to the same idea, so the definite article helps the reader follow it.","She then writes that the libraries help children, although she means libraries in general rather than a known set.","Removing the article makes the scope clearer.","Her teacher also checks determiners: each student has a role, but both teams share one display.","These choices are small, yet they tell readers whether the report describes one object, a known group, or a general category.","The editor does not replace every article mechanically.","She asks what the reader can already identify and whether the intended claim applies generally or specifically."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is reference. A student opens her report with a proposal for a reading corner. In the next sentence, the proposal refers to the same idea, so the definite article helps the reader follow it. Speaker two: My main point is scope. Determiners help readers identify the scope of a claim. A student opens her report with a proposal for a reading corner. In the next sentence, the proposal refers to the same idea, so the definite article helps the reader follow it. She then writes that the libraries help children, although she means libraries in general rather than a known set. Removing the article makes the scope clearer. Her teacher also checks determiners: each student has a role, but both teams share one display. These choices are small, yet they tell readers whether the report describes one object, a known group, or a general category. The editor does not replace every article mechanically. She asks what the reader can already identify and whether the intended claim applies generally or specifically.","audio":"/english-course/v7.23/en-b2-15.mp3","synthetic":true,"questions":[{"id":"en-b2-15-listening0","type":"choice","skill":"listening","prompt":"Ikkinchi proposal nega the?","answers":["the reader can identify the earlier idea"],"explanation":"Avvalgi a proposalga qaytadi.","hint":"a proposal → the proposal / information / each student","options":["the reader can identify the earlier idea","every noun needs the","it begins with a consonant"]},{"id":"en-b2-15-listening1","type":"choice","skill":"listening","prompt":"Umumiy libraries oldida nima?","answers":["no article"],"explanation":"Umumiy ko‘plik zero article.","hint":"a proposal → the proposal / information / each student","options":["no article","always the","always an"]},{"id":"en-b2-15-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["reference","scope"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"a proposal → the proposal / information / each student","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-15-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Each student has a role."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"a proposal → the proposal / information / each student","audio":"/english-course/v7.23/en-b2-15-dictation.mp3","transcript":"Each student has a role."}]},"writing":{"task":"Taklif matnida a/the/zero article va each/both bilan reference xaritasini yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"We have received a proposal for a reading corner. The proposal suggests using one quiet part of the library twice a week. Libraries provide information, but students also need space to discuss what they read. Each student would have a role in preparing the display, while both groups would share responsibility for keeping it tidy. This distinction matters: the report describes one particular proposal and one known library, while its claim about libraries and information is general. We recommend reviewing the proposal after a short trial.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["We received a proposal.","The proposal needs more evidence.","Libraries provide information."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Taklif matnida a/the/zero article va each/both bilan reference xaritasini yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Taklif matnida a/the/zero article va each/both bilan reference xaritasini yozing.","exit":[[{"id":"en-b2-15-exit0","type":"grammarFill","skill":"grammar","prompt":"We received ___ proposal.","answers":["a"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student"},{"id":"en-b2-15-exit1","type":"grammarFill","skill":"grammar","prompt":"___ proposal needs evidence. (oldingi taklif)","answers":["The"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student"},{"id":"en-b2-15-exit2","type":"grammarFill","skill":"grammar","prompt":"Each student ___ a role. (have)","answers":["has"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student"},{"id":"en-b2-15-exit3","type":"choice","skill":"grammar","prompt":"Ikkinchi proposal nega the?","answers":["the reader can identify the earlier idea"],"explanation":"Avvalgi a proposalga qaytadi.","hint":"a proposal → the proposal / information / each student","options":["the reader can identify the earlier idea","every noun needs the","it begins with a consonant"]},{"id":"en-b2-15-exit4","type":"choice","skill":"grammar","prompt":"Umumiy libraries oldida nima?","answers":["no article"],"explanation":"Umumiy ko‘plik zero article.","hint":"a proposal → the proposal / information / each student","options":["no article","always the","always an"]}],[{"id":"en-b2-15-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The proposal needs more evidence."],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","tokens":["The","proposal","needs","more","evidence."]},{"id":"en-b2-15-exit-b1","type":"grammarFill","skill":"grammar","prompt":"___ proposal needs evidence. (oldingi taklif)","answers":["The"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student"},{"id":"en-b2-15-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Each student has a role."],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","tokens":["Each","student","has","a","role."]},{"id":"en-b2-15-exit-b3","type":"choice","skill":"grammar","prompt":"Ikkinchi proposal nega the?","answers":["the reader can identify the earlier idea"],"explanation":"Avvalgi a proposalga qaytadi.","hint":"a proposal → the proposal / information / each student","options":["the reader can identify the earlier idea","every noun needs the","it begins with a consonant"]},{"id":"en-b2-15-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["It takes an hour to reach a university."],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","tokens":["It","takes","an","hour","to","reach","a","university."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki au