insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-16','en-b2-16',null,4,16,'published',1,'{"id":"en-b2-16","baseId":"en-b2-16","revision":1,"level":"B2","levelIndex":4,"order":16,"title":"Concession, purpose va result","objective":"Qarshi dalil, maqsad va oqibatni bog‘lovchi bilan aniq ajratasiz.","context":"Concession, purpose va result","prerequisites":["en-b2-15"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Although/even though + clause; despite/in spite of + noun yoki -ing.","So that + clause maqsad; so/such … that natija.","Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang."],"pattern":"although it is costly / despite the cost / so that / so useful that","examples":["Although the plan is costly, it may help.","Despite the cost, we support a trial.","We added labels so that visitors could navigate.","The room was so busy that we waited.","It was such a useful guide that we shared it.","Even though opinions differ, we can agree on a trial."],"vocabulary":[{"id":"en-b2-16-v0","term":"concession","meaning":"yon beruvchi dalil","ipa":"/kənˈseʃən/","collocation":"make a concession","example":"make a concession"},{"id":"en-b2-16-v1","term":"purpose","meaning":"maqsad","ipa":"/ˈpɜːpəs/","collocation":"state a purpose","example":"A reasoned report separates the purpose of a trial from the consequence of a past event."},{"id":"en-b2-16-v2","term":"consequence","meaning":"oqibat","ipa":"/ˈkɒnsɪkwəns/","collocation":"a likely consequence","example":"A reasoned report separates the purpose of a trial from the consequence of a past event."},{"id":"en-b2-16-v3","term":"trial","meaning":"sinov","ipa":"/ˈtraɪəl/","collocation":"a limited trial","example":"Despite the cost, we support a trial."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["although it is costly / despite the cost / so that / so useful that","Although the plan is costly, it may help.","Despite the cost, we support a trial."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Students need quiet space, but costs matter.","A short trial can collect attendance data.","Use the evidence to decide rather than assume."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The room was so busy that we waited.","audio":"/english-course/v7.23/en-b2-16-dictation.mp3"},"exercises":[{"id":"en-b2-16-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: ___ the cost, we support a trial.","answers":["Despite"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","options":["Despite","Although","However"]},{"id":"en-b2-16-gap","type":"grammarFill","skill":"grammar","prompt":"___ the cost, we support a trial.","answers":["Despite"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Although the plan is costly, it may help."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["Although","the","plan","is","costly,","it","may","help."]},{"id":"en-b2-16-fix","type":"correction","skill":"grammar","prompt":"Despite of the cost, we support a trial.","answers":["Despite the cost, we support a trial."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["yon beruvchi dalil","maqsad","oqibat","sinov"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"although it is costly / despite the cost / so that / so useful that","left":["concession","purpose","consequence","trial"],"options":["yon beruvchi dalil","maqsad","oqibat","sinov"]},{"id":"en-b2-16-transform","type":"transformation","skill":"grammar","prompt":"Despite bilan: Although the plan is costly, we support it.","answers":["Despite the cost, we support the plan."],"hint":"although it is costly / despite the cost / so that / so useful that","explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing."},{"id":"en-b2-16-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Students need quiet space, but costs matter.","A short trial can collect attendance data.","Use the evidence to decide rather than assume."],"answers":["Students need quiet space, but costs matter.\nA short trial can collect attendance data.\nUse the evidence to decide rather than assume."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-16-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["Although the plan is costly, it may help."],"tokens":["Although","the","plan","is","costly,","it","may","help."],"hint":"although it is costly / despite the cost / so that / so useful that","explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing."},{"id":"en-b2-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Reduced relative va participle clauses: Til vositasini tanlang: Students ___ outside need tickets. (wait)","answers":["waiting"],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked","options":["waiting","wait","waited"],"recap":true,"sourceLesson":"Reduced relative va participle clauses"},{"id":"en-b2-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Gerund va infinitive: ma’no o‘zgarishi: Til vositasini tanlang: Remember ___ lock the door.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","options":["to","for","that"],"recap":true,"sourceLesson":"Gerund va infinitive: ma’no o‘zgarishi"},{"id":"en-b2-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Articles va determiners: umumiydan aniqga: Til vositasini tanlang: We received ___ proposal.","answers":["a"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","options":["a","an","no article"],"recap":true,"sourceLesson":"Articles va determiners: umumiydan aniqga"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The school considers extending library hours. Although the plan would cost money, supporters argue that students need a quiet place after lessons. Critics agree with the aim but question whether enough students would attend. The school proposes a two-week trial so that it can collect attendance data before making a permanent decision. Last year, a popular event was so busy that the room became difficult to use. That result does not prove every extended session will be crowded. A reasoned report separates the purpose of a trial from the consequence of a past event. It also acknowledges the cost without treating it as a complete argument against the plan. Shared aims can make disagreement more productive when the uncertain facts are tested.","sentences":["The school considers extending library hours.","Although the plan would cost money, supporters argue that students need a quiet place after lessons.","Critics agree with the aim but question whether enough students would attend.","The school proposes a two-week trial so that it can collect attendance data before making a permanent decision.","Last year, a popular event was so busy that the room became difficult to use.","That result does not prove every extended session will be crowded.","A reasoned report separates the purpose of a trial from the consequence of a past event.","It also acknowledges the cost without treating it as a complete argument against the plan.","Shared aims can make disagreement more productive when the uncertain facts are tested."],"questions":[{"id":"en-b2-16-reading0","type":"choice","skill":"reading","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-reading1","type":"choice","skill":"reading","prompt":"Critics nimaga rozi?","answers":["the need for a quiet place"],"explanation":"Aimga rozi, attendancega shubha.","hint":"although it is costly / despite the cost / so that / so useful that","options":["the need for a quiet place","all costs are irrelevant","every session will be busy"]},{"id":"en-b2-16-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"although it is costly / despite the cost / so that / so useful that","options":["The school considers extending library hours.","Although the plan would cost money, supporters argue that students need a quiet place after lessons.","Critics agree with the aim but question whether enough students would attend.","The school proposes a two-week trial so that it can collect attendance data before making a permanent decision.","Last year, a popular event was so busy that the room became difficult to use.","That result does not prove every extended session will be crowded.","A reasoned report separates the purpose of a trial from the consequence of a past event.","It also acknowledges the cost without treating it as a complete argument against the plan.","Shared aims can make disagreement more productive when the uncertain facts are tested."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is trial. The school considers extending library hours. Although the plan would cost money, supporters argue that students need a quiet place after lessons. Speaker two: My main point is evidence. A shared aim still needs evidence about likely attendance. The school considers extending library hours. Although the plan would cost money, supporters argue that students need a quiet place after lessons. Critics agree with the aim but question whether enough students would attend. The school proposes a two-week trial so that it can collect attendance data before making a permanent decision. Last year, a popular event was so busy that the room became difficult to use. That result does not prove every extended session will be crowded. A reasoned report separates the purpose of a trial from the consequence of a past event. It also acknowledges the cost without treating it as a complete argument against the plan. Shared aims can make disagreement more productive when the uncertain facts are tested.","audio":"/english-course/v7.23/en-b2-16.mp3","synthetic":true,"questions":[{"id":"en-b2-16-listening0","type":"choice","skill":"listening","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-listening1","type":"choice","skill":"listening","prompt":"Critics nimaga rozi?","answers":["the need for a quiet place"],"explanation":"Aimga rozi, attendancega shubha.","hint":"although it is costly / despite the cost / so that / so useful that","options":["the need for a quiet place","all costs are irrelevant","every session will be busy"]},{"id":"en-b2-16-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["trial","evidence"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"although it is costly / despite the cost / so that / so useful that","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-16-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The room was so busy that we waited."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"although it is costly / despite the cost / so that / so useful that","audio":"/english-course/v7.23/en-b2-16-dictation.mp3","transcript":"The room was so busy that we waited."}]},"writing":{"task":"Advantages/disadvantages matnida qarshi dalil, maqsad va natijani ajrating.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Although longer library hours would cost money, they could provide a quiet place for students after lessons. Critics reasonably ask whether enough students would attend. We propose a two-week trial so that attendance can be measured before a permanent decision is made. The success of one crowded event should not be treated as proof that every session will be busy. Despite the uncertainty, a limited trial offers a practical way to compare the benefit with the cost. The aim is to test the plan, rather than win an argument through repetition.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Although the plan is costly, it may help.","Despite the cost, we support a trial.","We added labels so that visitors could navigate."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Advantages/disadvantages matnida qarshi dalil, maqsad va natijani ajrating. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Advantages/disadvantages matnida qarshi dalil, maqsad va natijani ajrating.","exit":[[{"id":"en-b2-16-exit0","type":"grammarFill","skill":"grammar","prompt":"___ the cost, we support a trial.","answers":["Despite"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit1","type":"grammarFill","skill":"grammar","prompt":"We added labels so ___ visitors could navigate.","answers":["that"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit2","type":"grammarFill","skill":"grammar","prompt":"It was ___ useful that we shared it.","answers":["so"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit3","type":"choice","skill":"grammar","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-exit4","type":"choice","skill":"grammar","prompt":"Critics nimaga rozi?","answers":["the need for a quiet place"],"explanation":"Aimga rozi, attendancega shubha.","hint":"although it is costly / despite the cost / so that / so useful that","options":["the need for a quiet place","all costs are irrelevant","every session will be busy"]}],[{"id":"en-b2-16-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Despite the cost, we support a trial."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["Despite","the","cost,","we","support","a","trial."]},{"id":"en-b2-16-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We added labels so ___ visitors could navigate.","answers":["that"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The room was so busy that we waited."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["The","room","was","so","busy","that","we","waited."]},{"id":"en-b2-16-exit-b3","type":"choice","skill":"grammar","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Even though opinions differ, we can agree on a trial."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["Even","though","opinions","differ,","we","can","agree","on","a","trial."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b2-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Reduced relative va participle clauses: Til vositasini tanlang: Students ___ outside need tickets. (wait)","answers":["waiting"],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked","options":["waiting","wait","waited"],"recap":true,"sourceLesson":"Reduced relative va participle clauses"},{"id":"en-b2-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Gerund va infinitive: ma’no o‘zgarishi: Til vositasini tanlang: Remember ___ lock the door.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","options":["to","for","that"],"recap":true,"sourceLesson":"Gerund va infinitive: ma’no o‘zgarishi"},{"id":"en-b2-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Articles va determiners: umumiydan aniqga: Til vositasini tanlang: We received ___ proposal.","answers":["a"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","options":["a","an","no article"],"recap":true,"sourceLesson":"Articles va determiners: umumiydan aniqga"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-17','en-b2-17',null,4,17,'published',1,'{"id":"en-b2-17","baseId":"en-b2-17","revision":1,"level":"B2","levelIndex":4,"order":17,"title":"Odobli e’tiroz va hedging","objective":"Fikrni yumshatib, dalil kuchiga mos aniqlik bilan bahslashasiz.","context":"Odobli e’tiroz va hedging","prerequisites":["en-b2-16"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["May/might, tends to, appears to xulosa kuchini chegaralaydi.","I see your point, but … kelishilgan qismdan e’tirozga o‘tadi.","Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin."],"pattern":"appears to / may suggest / I see your point, but","examples":["The result appears to support the plan.","This may suggest a useful pattern.","I see your point, but the sample is small.","The method tends to work better with clear instructions.","Could we consider another explanation?","I am not convinced that cost alone decides it."],"vocabulary":[{"id":"en-b2-17-v0","term":"sample","meaning":"namuna","ipa":"/ˈsɑːmpəl/","collocation":"a small sample","example":"I see your point, but the sample is small."},{"id":"en-b2-17-v1","term":"tentative","meaning":"dastlabki","ipa":"/ˈtentətɪv/","collocation":"a tentative conclusion","example":"a tentative conclusion"},{"id":"en-b2-17-v2","term":"challenge","meaning":"shubha ostiga qo‘ymoq","ipa":"/ˈtʃælɪndʒ/","collocation":"challenge a claim","example":"challenge a claim"},{"id":"en-b2-17-v3","term":"courteous","meaning":"hurmatli","ipa":"/ˈkɜːtiəs/","collocation":"a courteous disagreement","example":"Her objection is courteous because she recognises the useful work already done and proposes a larger survey."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["appears to / may suggest / I see your point, but","The result appears to support the plan.","This may suggest a useful pattern."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The early result is encouraging.","Only eight volunteers answered.","Keep the trial and gather broader evidence."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The method tends to work better with clear instructions.","audio":"/english-course/v7.23/en-b2-17-dictation.mp3"},"exercises":[{"id":"en-b2-17-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","options":["to","for","that"]},{"id":"en-b2-17-gap","type":"grammarFill","skill":"grammar","prompt":"The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The result appears to support the plan."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["The","result","appears","to","support","the","plan."]},{"id":"en-b2-17-fix","type":"correction","skill":"grammar","prompt":"Eight volunteers prove that every student agrees.","answers":["Eight volunteers suggest support, but do not prove that every student agrees."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["namuna","dastlabki","shubha ostiga qo‘ymoq","hurmatli"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"appears to / may suggest / I see your point, but","left":["sample","tentative","challenge","courteous"],"options":["namuna","dastlabki","shubha ostiga qo‘ymoq","hurmatli"]},{"id":"en-b2-17-transform","type":"transformation","skill":"grammar","prompt":"Ehtiyotkor qiling: The findings prove the plan works.","answers":["The findings may suggest that the plan works."],"hint":"appears to / may suggest / I see your point, but","explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi."},{"id":"en-b2-17-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The early result is encouraging.","Only eight volunteers answered.","Keep the trial and gather broader evidence."],"answers":["The early result is encouraging.\nOnly eight volunteers answered.\nKeep the trial and gather broader evidence."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A survey of eight volunteers finds that most prefer the new reading corner. The organiser announces that all students clearly support it. Another student agrees that the result is encouraging but points out that the sample is small and voluntary. She says the findings may suggest a useful pattern, not prove a school-wide preference. This wording limits the claim to what the evidence supports. Her objection is courteous because she recognises the useful work already done and proposes a larger survey. Hedging is not an excuse to avoid taking a position. The student still recommends keeping the corner during the trial. She simply separates a practical recommendation from a certainty the survey cannot establish.","sentences":["A survey of eight volunteers finds that most prefer the new reading corner.","The organiser announces that all students clearly support it.","Another student agrees that the result is encouraging but points out that the sample is small and voluntary.","She says the findings may suggest a useful pattern, not prove a school-wide preference.","This wording limits the claim to what the evidence supports.","Her objection is courteous because she recognises the useful work already done and proposes a larger survey.","Hedging is not an excuse to avoid taking a position.","The student still recommends keeping the corner during the trial.","She simply separates a practical recommendation from a certainty the survey cannot establish."],"questions":[{"id":"en-b2-17-reading0","type":"choice","skill":"reading","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-reading1","type":"choice","skill":"reading","prompt":"Student qanday pozitsiya oladi?","answers":["keep the trial while gathering better evidence"],"explanation":"Tavsiyasi aniq, xulosasi cheklangan.","hint":"appears to / may suggest / I see your point, but","options":["keep the trial while gathering better evidence","close immediately","claim certainty"]},{"id":"en-b2-17-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"appears to / may suggest / I see your point, but","options":["A survey of eight volunteers finds that most prefer the new reading corner.","The organiser announces that all students clearly support it.","Another student agrees that the result is encouraging but points out that the sample is small and voluntary.","She says the findings may suggest a useful pattern, not prove a school-wide preference.","This wording limits the claim to what the evidence supports.","Her objection is courteous because she recognises the useful work already done and proposes a larger survey.","Hedging is not an excuse to avoid taking a position.","The student still recommends keeping the corner during the trial.","She simply separates a practical recommendation from a certainty the survey cannot establish."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is sample. A survey of eight volunteers finds that most prefer the new reading corner. The organiser announces that all students clearly support it. Speaker two: My main point is tentative. The result is encouraging, but the conclusion should remain tentative. A survey of eight volunteers finds that most prefer the new reading corner. The organiser announces that all students clearly support it. Another student agrees that the result is encouraging but points out that the sample is small and voluntary. She says the findings may suggest a useful pattern, not prove a school-wide preference. This wording limits the claim to what the evidence supports. Her objection is courteous because she recognises the useful work already done and proposes a larger survey. Hedging is not an excuse to avoid taking a position. The student still recommends keeping the corner during the trial. She simply separates a practical recommendation from a certainty the survey cannot establish.","audio":"/english-course/v7.23/en-b2-17.mp3","synthetic":true,"questions":[{"id":"en-b2-17-listening0","type":"choice","skill":"listening","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-listening1","type":"choice","skill":"listening","prompt":"Student qanday pozitsiya oladi?","answers":["keep the trial while gathering better evidence"],"explanation":"Tavsiyasi aniq, xulosasi cheklangan.","hint":"appears to / may suggest / I see your point, but","options":["keep the trial while gathering better evidence","close immediately","claim certainty"]},{"id":"en-b2-17-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["sample","tentative"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"appears to / may suggest / I see your point, but","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-17-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The method tends to work better with clear instructions."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"appears to / may suggest / I see your point, but","audio":"/english-course/v7.23/en-b2-17-dictation.mp3","transcript":"The method tends to work better with clear instructions."}]},"writing":{"task":"Kichik surveyga asoslangan xulosani cheklov va amaliy tavsiya bilan yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The survey result is encouraging: most of the eight volunteers preferred the reading corner. However, the sample is too small and selective to establish the view of all students. I recommend keeping the corner during the trial while collecting responses from a broader group. This position recognises the benefit already observed without claiming more than the evidence supports. I see the organiser’s point about enthusiasm, but we should distinguish support among volunteers from school-wide demand. A larger survey could help decide whether the arrangement should become permanent.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The result appears to support the plan.","This may suggest a useful pattern.","I see your point, but the sample is small."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Kichik surveyga asoslangan xulosani cheklov va amaliy tavsiya bilan yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Kichik surveyga asoslangan xulosani cheklov va amaliy tavsiya bilan yozing.","exit":[[{"id":"en-b2-17-exit0","type":"grammarFill","skill":"grammar","prompt":"The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit1","type":"grammarFill","skill":"grammar","prompt":"This ___ suggest a pattern. (ehtimol)","answers":["may"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit2","type":"grammarFill","skill":"grammar","prompt":"I see your point, ___ the sample is small.","answers":["but"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit3","type":"choice","skill":"grammar","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-exit4","type":"choice","skill":"grammar","prompt":"Student qanday pozitsiya oladi?","answers":["keep the trial while gathering better evidence"],"explanation":"Tavsiyasi aniq, xulosasi cheklangan.","hint":"appears to / may suggest / I see your point, but","options":["keep the trial while gathering better evidence","close immediately","claim certainty"]}],[{"id":"en-b2-17-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["This may suggest a useful pattern."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["This","may","suggest","a","useful","pattern."]},{"id":"en-b2-17-exit-b1","type":"grammarFill","skill":"grammar","prompt":"This ___ suggest a pattern. (ehtimol)","answers":["may"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The method tends to work better with clear instructions."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["The","method","tends","to","work","better","with","clear","instructions."]},{"id":"en-b2-17-exit-b3","type":"choice","skill":"grammar","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I am not convinced that cost alone decides it."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["I","am","not","convinced","that","cost","alone","decides","it."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-18','en-b2-18',null,4,18,'published',1,'{"id":"en-b2-18","baseId":"en-b2-18","revision":1,"level":"B2","levelIndex":4,"order":18,"title":"Register: formal email va samimiy xabar","objective":"Bitta maqsadni auditoriyaga mos ikki uslubda ifodalaysiz.","context":"Register: formal email va samimiy xabar","prerequisites":["en-b2-17"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas.","Could you please … va I would appreciate … so‘rovni yumshatadi.","Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning."],"pattern":"Could you please clarify …? / Can you tell me …?","examples":["Could you please clarify the deadline?","I would appreciate a written reply.","Please find the revised plan attached.","Can you tell me when it is due?","Thanks for checking this for me.","I am writing to request more information."],"vocabulary":[{"id":"en-b2-18-v0","term":"clarify","meaning":"aniqlashtirmoq","ipa":"/ˈklærɪfaɪ/","collocation":"clarify a deadline","example":"Could you please clarify the deadline?"},{"id":"en-b2-18-v1","term":"attached","meaning":"ilova qilingan","ipa":"/əˈtætʃt/","collocation":"the attached plan","example":"Please find the revised plan attached."},{"id":"en-b2-18-v2","term":"recipient","meaning":"qabul qiluvchi","ipa":"/rɪˈsɪpiənt/","collocation":"a message recipient","example":"a message recipient"},{"id":"en-b2-18-v3","term":"tone","meaning":"ohang","ipa":"/təʊn/","collocation":"a respectful tone","example":"a respectful tone"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["Could you please clarify …? / Can you tell me …?","Could you please clarify the deadline?","I would appreciate a written reply."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The recipient needs a clear request.","The notice omits the submission deadline.","Ask one precise question in a respectful tone."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Can you tell me when it is due?","audio":"/english-course/v7.23/en-b2-18-dictation.mp3"},"exercises":[{"id":"en-b2-18-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","options":["clarify","clarifying","clarified"]},{"id":"en-b2-18-gap","type":"grammarFill","skill":"grammar","prompt":"Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Could you please clarify the deadline?"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","tokens":["Could","you","please","clarify","the","deadline?"]},{"id":"en-b2-18-fix","type":"correction","skill":"grammar","prompt":"Tell me the date now, office.","answers":["Could you please clarify the deadline?"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["aniqlashtirmoq","ilova qilingan","qabul qiluvchi","ohang"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Could you please clarify …? / Can you tell me …?","left":["clarify","attached","recipient","tone"],"options":["aniqlashtirmoq","ilova qilingan","qabul qiluvchi","ohang"]},{"id":"en-b2-18-transform","type":"transformation","skill":"grammar","prompt":"Formal qiling: Tell me when it is due.","answers":["Could you please clarify the deadline?"],"hint":"Could you please clarify …? / Can you tell me …?","explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas."},{"id":"en-b2-18-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The recipient needs a clear request.","The notice omits the submission deadline.","Ask one precise question in a respectful tone."],"answers":["The recipient needs a clear request.\nThe notice omits the submission deadline.\nAsk one precise question in a respectful tone."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-18-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["clarify","attached","recipient","tone"],"options":["clarify a deadline","the attached plan","a message recipient","a respectful tone"],"answers":["clarify a deadline","the attached plan","a message recipient","a respectful tone"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."},{"id":"en-b2-18-register","type":"register","skill":"writing","prompt":"Maktab ofisiga rasmiy so‘rovni tanlang.","options":["Could you please clarify the deadline?","Tell me now!","Hey, what’s up?"],"answers":["Could you please clarify the deadline?"],"hint":"Murojaat va so‘rov hurmatli bo‘lsin.","explanation":"Could you please … aniq va hurmatli rasmiy so‘rov."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Two emails ask for the same deadline. A message to a friend says, “Can you tell me when it is due?” A message to the school office says, “Could you please clarify the submission deadline?” The second is not better English in every situation; it suits a different relationship. A student initially writes a very long formal email with several vague phrases and no clear request. The teacher asks her to simplify it. She keeps a polite greeting, states the purpose, and asks one precise question. Register includes clarity as well as politeness. Choosing an audience does not require hiding meaning behind elaborate words. The office can answer more quickly because the revised message makes the requested action easy to identify.","sentences":["Two emails ask for the same deadline.","A message to a friend says, “Can you tell me when it is due?","” A message to the school office says, “Could you please clarify the submission deadline?","” The second is not better English in every situation; it suits a different relationship.","A student initially writes a very long formal email with several vague phrases and no clear request.","The teacher asks her to simplify it.","She keeps a polite greeting, states the purpose, and asks one precise question.","Register includes clarity as well as politeness.","Choosing an audience does not require hiding meaning behind elaborate words.","The office can answer more quickly because the revised message makes the requested action easy to identify."],"questions":[{"id":"en-b2-18-reading0","type":"choice","skill":"reading","prompt":"Ikkinchi xabar nega mos?","answers":["it suits the office relationship"],"explanation":"Auditoriya register tanlaydi.","hint":"Could you please clarify …? / Can you tell me …?","options":["it suits the office relationship","it is always superior","it must be longer"]},{"id":"en-b2-18-reading1","type":"choice","skill":"reading","prompt":"Uzun email muammosi?","answers":["the request was unclear"],"explanation":"Murakkablik aniqlikni yo‘qotgan.","hint":"Could you please clarify …? / Can you tell me …?","options":["the request was unclear","it contained a greeting","it asked one precise question"]},{"id":"en-b2-18-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Could you please clarify …? / Can you tell me …?","options":["Two emails ask for the same deadline.","A message to a friend says, “Can you tell me when it is due?","” A message to the school office says, “Could you please clarify the submission deadline?","” The second is not better English in every situation; it suits a different relationship.","A student initially writes a very long formal email with several vague phrases and no clear request.","The teacher asks her to simplify it.","She keeps a polite greeting, states the purpose, and asks one precise question.","Register includes clarity as well as politeness.","Choosing an audience does not require hiding meaning behind elaborate words.","The office can answer more quickly because the revised message makes the requested action easy to identify."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is recipient. Two emails ask for the same deadline. A message to a friend says, “Can you tell me when it is due? Speaker two: My main point is clarity. A formal request should remain easy to understand. Two emails ask for the same deadline. A message to a friend says, “Can you tell me when it is due?” A message to the school office says, “Could you please clarify the submission deadline?” The second is not better English in every situation; it suits a different relationship. A student initially writes a very long formal email with several vague phrases and no clear request. The teacher asks her to simplify it. She keeps a polite greeting, states the purpose, and asks one precise question. Register includes clarity as well as politeness. Choosing an audience does not require hiding meaning behind elaborate words. The office can answer more quickly because the revised message makes the requested action easy to identify.","audio":"/english-course/v7.23/en-b2-18.mp3","synthetic":true,"questions":[{"id":"en-b2-18-listening0","type":"choice","skill":"listening","prompt":"Ikkinchi xabar nega mos?","answers":["it suits the office relationship"],"explanation":"Auditoriya register tanlaydi.","hint":"Could you please clarify …? / Can you tell me …?","options":["it suits the office relationship","it is always superior","it must be longer"]},{"id":"en-b2-18-listening1","type":"choice","skill":"listening","prompt":"Uzun email muammosi?","answers":["the request was unclear"],"explanation":"Murakkablik aniqlikni yo‘qotgan.","hint":"Could you please clarify …? / Can you tell me …?","options":["the request was unclear","it contained a greeting","it asked one precise question"]},{"id":"en-b2-18-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["recipient","clarity"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Could you please clarify …? / Can you tell me …?","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-18-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Can you tell me when it is due?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Could you please clarify …? / Can you tell me …?","audio":"/english-course/v7.23/en-b2-18-dictation.mp3","transcript":"Can you tell me when it is due?"}]},"writing":{"task":"Bir so‘rovni do‘stga va maktab ofisiga mos ikki xabarda yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Dear school office, I am writing to ask about the deadline for submitting our club proposal. The notice gives the meeting date but does not state when proposals should arrive. Could you please clarify the submission deadline and confirm whether an electronic copy is acceptable? We would like to plan the final review before sending our work. I would appreciate a written reply so that I can share the information accurately with the group. Thank you for your help. Kind regards, Lola.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Could you please clarify the deadline?","I would appreciate a written reply.","Please find the revised plan attached."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Bir so‘rovni do‘stga va maktab ofisiga mos ikki xabarda yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bir so‘rovni do‘stga va maktab ofisiga mos ikki xabarda yozing.","exit":[[{"id":"en-b2-18-exit0","type":"grammarFill","skill":"grammar","prompt":"Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-exit1","type":"grammarFill","skill":"grammar","prompt":"I would appreciate ___ written reply.","answers":["a"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-exit2","type":"grammarFill","skill":"grammar","prompt":"Please find the plan ___. (attach)","answers":["attached"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-exit3","type":"choice","skill":"grammar","prompt":"Ikkinch