":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-19','en-b2-19',null,4,19,'published',1,'{"id":"en-b2-19","baseId":"en-b2-19","revision":1,"level":"B2","levelIndex":4,"order":19,"title":"Word formation: so‘z oilalari","objective":"So‘zning vazifasiga ko‘ra noun, verb, adjective va adverb shaklini tanlaysiz.","context":"Word formation: so‘z oilalari","prerequisites":["en-b2-18"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Success noun, succeed verb, successful adjective, successfully adverb.","Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring.","Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless."],"pattern":"succeed → success → successful → successfully","examples":["The trial was successful.","The team completed it successfully.","Success depends on careful preparation.","They hope to succeed next time.","The instructions were useful.","The plan was impossible within one day."],"vocabulary":[{"id":"en-b2-19-v0","term":"successful","meaning":"muvaffaqiyatli","ipa":"/səkˈsesfəl/","collocation":"a successful trial","example":"The trial was successful."},{"id":"en-b2-19-v1","term":"successfully","meaning":"muvaffaqiyat bilan","ipa":"/səkˈsesfəli/","collocation":"complete successfully","example":"The team completed it successfully."},{"id":"en-b2-19-v2","term":"reliable","meaning":"ishonchli","ipa":"/rɪˈlaɪəbəl/","collocation":"reliable evidence","example":"The club report describes a successful trial, then claims that success proves the plan is reliable."},{"id":"en-b2-19-v3","term":"reliability","meaning":"ishonchlilik","ipa":"/rɪˌlaɪəˈbɪləti/","collocation":"check reliability","example":"The teacher asks what reliability means in this context."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["succeed → success → successful → successfully","The trial was successful.","The team completed it successfully."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The first trial succeeded.","A second group tested the same instructions.","Evaluate reliability across similar conditions."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"They hope to succeed next time.","audio":"/english-course/v7.23/en-b2-19-dictation.mp3"},"exercises":[{"id":"en-b2-19-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","options":["successful","success","successfully"]},{"id":"en-b2-19-gap","type":"grammarFill","skill":"grammar","prompt":"The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The trial was successful."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","tokens":["The","trial","was","successful."]},{"id":"en-b2-19-fix","type":"correction","skill":"grammar","prompt":"The team worked successful.","answers":["The team worked successfully."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["muvaffaqiyatli","muvaffaqiyat bilan","ishonchli","ishonchlilik"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"succeed → success → successful → successfully","left":["successful","successfully","reliable","reliability"],"options":["muvaffaqiyatli","muvaffaqiyat bilan","ishonchli","ishonchlilik"]},{"id":"en-b2-19-transform","type":"transformation","skill":"grammar","prompt":"Adverb bilan: Their work was successful.","answers":["They worked successfully."],"hint":"succeed → success → successful → successfully","explanation":"Success noun, succeed verb, successful adjective, successfully adverb."},{"id":"en-b2-19-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The first trial succeeded.","A second group tested the same instructions.","Evaluate reliability across similar conditions."],"answers":["The first trial succeeded.\nA second group tested the same instructions.\nEvaluate reliability across similar conditions."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The club report describes a successful trial, then claims that success proves the plan is reliable. The teacher asks what reliability means in this context. One positive event is evidence of success, but a reliable process should work consistently under similar conditions. The group repeats the trial with another class and checks whether the instructions can be followed without extra help. They also edit word forms. “The team worked successful” becomes “The team worked successfully.” Selecting the right suffix matters grammatically, while selecting the right concept matters logically. A word family can help express an idea precisely only when the writer understands the relation between the words. The revised report separates a successful event from evidence of reliability.","sentences":["The club report describes a successful trial, then claims that success proves the plan is reliable.","The teacher asks what reliability means in this context.","One positive event is evidence of success, but a reliable process should work consistently under similar conditions.","The group repeats the trial with another class and checks whether the instructions can be followed without extra help.","They also edit word forms.","“The team worked successful” becomes “The team worked successfully.","” Selecting the right suffix matters grammatically, while selecting the right concept matters logically.","A word family can help express an idea precisely only when the writer understands the relation between the words.","The revised report separates a successful event from evidence of reliability."],"questions":[{"id":"en-b2-19-reading0","type":"choice","skill":"reading","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-reading1","type":"choice","skill":"reading","prompt":"Successfully qanday ishlaydi?","answers":["it describes how they worked"],"explanation":"Adverb fe’lga.","hint":"succeed → success → successful → successfully","options":["it describes how they worked","it names an event","it describes a noun only"]},{"id":"en-b2-19-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"succeed → success → successful → successfully","options":["The club report describes a successful trial, then claims that success proves the plan is reliable.","The teacher asks what reliability means in this context.","One positive event is evidence of success, but a reliable process should work consistently under similar conditions.","The group repeats the trial with another class and checks whether the instructions can be followed without extra help.","They also edit word forms.","“The team worked successful” becomes “The team worked successfully.","” Selecting the right suffix matters grammatically, while selecting the right concept matters logically.","A word family can help express an idea precisely only when the writer understands the relation between the words.","The revised report separates a successful event from evidence of reliability."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is reliability. The club report describes a successful trial, then claims that success proves the plan is reliable. The teacher asks what reliability means in this context. Speaker two: My main point is consistency. Reliability requires more than one successful event. The club report describes a successful trial, then claims that success proves the plan is reliable. The teacher asks what reliability means in this context. One positive event is evidence of success, but a reliable process should work consistently under similar conditions. The group repeats the trial with another class and checks whether the instructions can be followed without extra help. They also edit word forms. “The team worked successful” becomes “The team worked successfully.” Selecting the right suffix matters grammatically, while selecting the right concept matters logically. A word family can help express an idea precisely only when the writer understands the relation between the words. The revised report separates a successful event from evidence of reliability.","audio":"/english-course/v7.23/en-b2-19.mp3","synthetic":true,"questions":[{"id":"en-b2-19-listening0","type":"choice","skill":"listening","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-listening1","type":"choice","skill":"listening","prompt":"Successfully qanday ishlaydi?","answers":["it describes how they worked"],"explanation":"Adverb fe’lga.","hint":"succeed → success → successful → successfully","options":["it describes how they worked","it names an event","it describes a noun only"]},{"id":"en-b2-19-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["reliability","consistency"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"succeed → success → successful → successfully","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-19-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["They hope to succeed next time."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"succeed → success → successful → successfully","audio":"/english-course/v7.23/en-b2-19-dictation.mp3","transcript":"They hope to succeed next time."}]},"writing":{"task":"Trial reportda word family va success/reliability farqini qo‘llang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The first trial was successful, and the team completed the task successfully. However, one success does not establish the reliability of the process. We repeated the activity with another class to see whether the instructions could be followed without extra help. The second group also completed the task, although it needed more time. We therefore have encouraging evidence of consistency, but we should continue checking the method under similar conditions. The report uses different word forms to describe the result, the action, and the quality being evaluated.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The trial was successful.","The team completed it successfully.","Success depends on careful preparation."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Trial reportda word family va success/reliability farqini qo‘llang. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Trial reportda word family va success/reliability farqini qo‘llang.","exit":[[{"id":"en-b2-19-exit0","type":"grammarFill","skill":"grammar","prompt":"The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit1","type":"grammarFill","skill":"grammar","prompt":"They worked ___. (successful)","answers":["successfully"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit2","type":"grammarFill","skill":"grammar","prompt":"They hope to ___. (success)","answers":["succeed"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit3","type":"choice","skill":"grammar","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-exit4","type":"choice","skill":"grammar","prompt":"Successfully qanday ishlaydi?","answers":["it describes how they worked"],"explanation":"Adverb fe’lga.","hint":"succeed → success → successful → successfully","options":["it describes how they worked","it names an event","it describes a noun only"]}],[{"id":"en-b2-19-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The team completed it successfully."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","tokens":["The","team","completed","it","successfully."]},{"id":"en-b2-19-exit-b1","type":"grammarFill","skill":"grammar","prompt":"They worked ___. (successful)","answers":["successfully"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They hope to succeed next time."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","tokens":["They","hope","to","succeed","next","time."]},{"id":"en-b2-19-exit-b3","type":"choice","skill":"grammar","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.